mapper.insert:
INSERT INTO identity_principals (
    principal_id, idp_issuer, idp_subject, principal_type, provisioning_status, version
) VALUES (
    #{principalId}, #{idpIssuer}, #{idpSubject}, #{principalType}, #{provisioningStatus}, #{version}
)

mapper.select:
SELECT *
FROM identity_principals
WHERE idp_issuer = #{idpIssuer} AND idp_subject = #{idpSubject}

mapper.update:
UPDATE identity_principals
SET provisioning_status = #{newStatus},
    idp_subject = COALESCE(#{idpSubject}, idp_subject),
    version = version + 1
WHERE principal_id = #{principalId}
  AND version = #{expectedVersion}

mapper.select:
SELECT *
FROM identity_principals


        AND principal_type = #{principalType}


        AND provisioning_status = #{provisioningStatus}


        AND principal_id IN (
            SELECT ra.principal_id
            FROM iam_role_assignments ra
            WHERE ra.role_id = #{roleId}
              AND ra.assignment_status = 'ACTIVE'
              AND ra.valid_from <= #{now}
              AND (ra.valid_until IS NULL OR ra.valid_until > #{now})

                  AND ra.scope_type = #{scopeType}


                  AND ra.scope_id = #{scopeId}

        )


        AND principal_id IN (
            SELECT ra.principal_id
            FROM iam_role_assignments ra
            JOIN iam_roles r ON ra.role_id = r.role_id
            WHERE r.role_code = #{roleCode}
              AND ra.assignment_status = 'ACTIVE'
              AND ra.valid_from <= #{now}
              AND (ra.valid_until IS NULL OR ra.valid_until > #{now})

                  AND ra.scope_type = #{scopeType}


                  AND ra.scope_id = #{scopeId}

        )


        AND principal_id IN (
            SELECT ra.principal_id
            FROM iam_role_assignments ra
            WHERE ra.scope_type = #{scopeType}
              AND ra.assignment_status = 'ACTIVE'
              AND ra.valid_from <= #{now}
              AND (ra.valid_until IS NULL OR ra.valid_until > #{now})

                  AND ra.scope_id = #{scopeId}

        )


        AND (
            CAST(principal_id AS TEXT) ILIKE CONCAT('%', #{search}, '%')

                OR idp_subject IN

                    #{subj}


        )


ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

